<?php require_once __DIR__.'/../includes/functions.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();db()->prepare('INSERT INTO homepage_sections(section_key,title,content,is_active,sort_order) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title),content=VALUES(content),is_active=VALUES(is_active),sort_order=VALUES(sort_order)')->execute([$_POST['section_key'],$_POST['title'],json_encode(['text'=>$_POST['content']],JSON_UNESCAPED_UNICODE),isset($_POST['is_active'])?1:0,$_POST['sort_order']]);flash('success','تم حفظ قسم الصفحة الرئيسية.');header('Location: '.base('admin/homepage.php'));exit;}$adminTitle='منشئ الصفحة الرئيسية';$rows=db()->query('SELECT * FROM homepage_sections ORDER BY sort_order')->fetchAll();include 'header.php';?><form class="form" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><div><label>معرّف القسم</label><input name="section_key" placeholder="testimonials" required></div><div><label>العنوان</label><input name="title" required></div><div><label>الترتيب</label><input name="sort_order" type="number" value="0"></div><div><label><input type="checkbox" name="is_active" checked> ظاهر</label></div><div class="full"><label>المحتوى</label><textarea name="content"></textarea></div><button class="button gold">حفظ القسم</button></form><div class="panel"><table class="table"><tr><th>القسم</th><th>العنوان</th><th>الظهور</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['section_key'])?></td><td><?=e($r['title'])?></td><td><?=$r['is_active']?'ظاهر':'مخفي'?></td></tr><?php endforeach;?></table></div><?php include 'footer.php';?>
